package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.OpenIntToDoubleHashMap.Iterator;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for OpenMapRealVector.ebeMultiply
 */
public class OpenMapRealVector_ebeMultiply_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testEbeMultiplyWithSparseVector() {
        // Setup: sparse vector [0, 5.0, 0, 10.0]
        OpenMapRealVector v1 = new OpenMapRealVector(4);
        v1.setEntry(1, 5.0);
        v1.setEntry(3, 10.0);

        // Multiplier vector [2.0, 3.0, 4.0, 5.0]
        double[] multiplierArray = {2.0, 3.0, 4.0, 5.0};
        RealVector v2 = new ArrayRealVector(multiplierArray);

        // Expected result: [0, 5.0*3.0, 0, 10.0*5.0] = [0, 15.0, 0, 50.0]
        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(4, result.getDimension());
        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(15.0, result.getEntry(1), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(2), EPSILON);
        Assert.assertEquals(50.0, result.getEntry(3), EPSILON);
    }

    @Test
    public void testEbeMultiplyWithEmptyVector() {
        // Setup: empty sparse vector
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        // v1 has no entries set (all zero)

        double[] multiplierArray = {1.0, 2.0, 3.0};
        RealVector v2 = new ArrayRealVector(multiplierArray);

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(3, result.getDimension());
        // Since v1 has no entries, the iterator in ebeMultiply won't run
        // The result should be a copy of v1 (all zeros)
        for (int i = 0; i < 3; i++) {
            Assert.assertEquals(0.0, result.getEntry(i), EPSILON);
        }
    }

    @Test
    public void testEbeMultiplyDimensionMismatch() {
        // Setup: dimension 3
        OpenMapRealVector v1 = new OpenMapRealVector(3);
        v1.setEntry(0, 1.0);

        // Multiplier: dimension 2
        RealVector v2 = new ArrayRealVector(new double[]{1.0, 1.0});

        // Should throw DimensionMismatchException due to checkVectorDimensions(v.getDimension())
        try {
            v1.ebeMultiply(v2);
            Assert.fail("Expected DimensionMismatchException");
        } catch (DimensionMismatchException e) {
            // Success
        }
    }

    @Test
    public void testEbeMultiplyWithZeroMultiplier() {
        // Setup: v1 = [1.0, 2.0], v2 = [0.0, 0.0]
        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 1.0);
        v1.setEntry(1, 2.0);

        double[] multiplierArray = {0.0, 0.0};
        RealVector v2 = new ArrayRealVector(multiplierArray);

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(0.0, result.getEntry(0), EPSILON);
        Assert.assertEquals(0.0, result.getEntry(1), EPSILON);
    }

    @Test
    public void testEbeMultiplyImmutability() {
        // Ensure the original vector is not modified
        OpenMapRealVector v1 = new OpenMapRealVector(2);
        v1.setEntry(0, 10.0);

        RealVector v2 = new ArrayRealVector(new double[]{2.0, 2.0});

        OpenMapRealVector result = v1.ebeMultiply(v2);

        Assert.assertEquals(10.0, v1.getEntry(0), EPSILON);
        Assert.assertEquals(20.0, result.getEntry(0), EPSILON);
    }
}
